const test = require('node:test');
const assert = require('node:assert/strict');
const { exportShelves } = require('../shelves.cjs');
test('TSV header and data use the same delimiter', () => {
  const rows = Object.freeze([Object.freeze({shelf:'B-7',books:12}),Object.freeze({shelf:'中文架',books:0})]);
  assert.equal(exportShelves(rows), 'shelf\tbooks\nB-7\t12\n中文架\t0\n');
  assert.equal(exportShelves([]), 'shelf\tbooks\n');
  assert.equal(exportShelves([{shelf:'',books:3}]), 'shelf\tbooks\n\t3\n');
});

